-- Step 1: Create a trace to capture queries
DECLARE @TraceID INT;
EXEC sp_trace_create @TraceID OUTPUT, 0, N'C:\Traces\WorkloadTrace.trc';

-- Step 2: Set events to capture
EXEC sp_trace_setevent @TraceID, 10, 1, 1;  -- RPC:Completed, TextData
EXEC sp_trace_setevent @TraceID, 12, 1, 1;  -- SQL:BatchCompleted, TextData

-- Step 3: Set filter on database
EXEC sp_trace_setfilter @TraceID, 11, 0, 6, N'AdventureWorks'; -- DatabaseID filter

-- Step 4: Start the trace
EXEC sp_trace_setstatus @TraceID, 1;

-- After capturing workload, stop the trace
EXEC sp_trace_setstatus @TraceID, 0;
EXEC sp_trace_setstatus @TraceID, 2;
